export const bitcoinAddress='36QW21MQQxUK7ohBQnvP5itipe4bFx91Bo';
export const supportLinks=[['Ko-fi','https://ko-fi.com/muneb','Support a little more room for writing.'],['Buy Me a Coffee','https://www.buymeacoffee.com/muneebwanee','A small thank-you for the studio.'],['Liberapay','https://liberapay.com/muneeb/donate','Offer recurring support.'],['Saweria','https://saweria.co/muneeb','Another way to contribute.']];
export function supportPage({I,B}){return `<div class="page support-page"><header class="page-intro"><div><h1>Help the next chapter happen.</h1><p>BookWiz is created and maintained by muneebwanee. If it earns a place on your desk, here are a few ways to help it grow.</p></div></header><section class="support-intro"><img src="assets/icon.svg" width="64" height="64" alt=""><div><h2>A private room. A shared effort.</h2><p>Star the project, share an idea, improve a translation, or contribute code. Every thoughtful contribution makes this room a little better.</p><div class="row wrap gap8"><a class="btn primary" href="https://github.com/muneebwanee/BookWizOfficial" target="_blank" rel="noopener">${I('heart')} Star BookWiz</a><a class="btn secondary" href="https://github.com/muneebwanee/BookWizOfficial/blob/HEAD/CONTRIBUTING.md" target="_blank" rel="noopener">${I('users')} Become a contributor</a></div></div></section><section class="support-payments" aria-labelledby="support-title"><h2 id="support-title">Keep the room open.</h2><p>Donations are optional. They go directly to the creator through the service you choose.</p><div class="payment-list">${supportLinks.map(([name,url,detail])=>`<a class="payment-row" href="${url}" target="_blank" rel="noopener"><div><strong>${name}</strong><span>${detail}</span></div>${I('external')}</a>`).join('')}</div><div class="bitcoin-support"><div><h3>Bitcoin</h3><p>Send directly to this address. Check it in your wallet before confirming.</p></div><label class="field"><span>Bitcoin address</span><input id="bitcoin-address" value="${bitcoinAddress}" readonly spellcheck="false" autocomplete="off"></label><div class="row wrap gap8">${B('copy-bitcoin','Copy address','file','secondary')}<a class="btn quiet" href="bitcoin:${bitcoinAddress}?label=BookWiz">Open wallet ${I('external')}</a></div><p id="bitcoin-status" class="small muted" role="status"></p></div></section><section class="support-community"><div><h2>Made better, together.</h2><p>Meet the people contributing to BookWiz, or bring your first idea to the project.</p><a class="text-link" href="https://github.com/muneebwanee/BookWizOfficial/graphs/contributors" target="_blank" rel="noopener">View contributors ${I('external')}</a></div><div><h2>Need a hand?</h2><p>Find help, report a problem, or learn how to keep your library safe.</p>${B('support','Help & troubleshooting','help','secondary')}</div></section><p class="support-signature">BookWiz · by <a href="https://github.com/muneebwanee" target="_blank" rel="noopener">muneebwanee</a></p></div>`;}
